begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.users(id) values('00000000-0000-4000-8000-000000009801'),('00000000-0000-4000-8000-000000009802');
select ok(not private.account_playgrounds_allowed('00000000-0000-4000-8000-000000009801'),'free account cannot run arbitrary code');
insert into private.account_benefits(id,user_id,benefit_key,amount,granted_by,reason) values(gen_random_uuid(),'00000000-0000-4000-8000-000000009801','feature.learn.playgrounds',1,'00000000-0000-4000-8000-000000009802','Disposable benefit fixture');
select ok(private.account_playgrounds_allowed('00000000-0000-4000-8000-000000009801'),'active benefit admits free account');
select ok(not has_function_privilege('authenticated','private.create_learn_playground(uuid,text,text,uuid)','EXECUTE'),'browser cannot forge playground owners');
select ok(not has_table_privilege('anon','private.learn_playgrounds','SELECT'),'anonymous callers cannot read files');
create temp table project(id uuid);
insert into project select private.create_learn_playground('00000000-0000-4000-8000-000000009801','Fixture','python');
select is((private.read_learn_playgrounds('00000000-0000-4000-8000-000000009802',(select id from project))->'projects')::text,'[]','foreign owner cannot list project');
select is(private.playground_collaboration_scope('00000000-0000-4000-8000-000000009802',(select id from project)),null::jsonb,'uninvited collaborator cannot join');
select is(private.publish_learn_playground('00000000-0000-4000-8000-000000009801',(select id from project),0,'playgrounds/'||(select id from project)||'/'||gen_random_uuid(),'python main.py','[]'::jsonb),1,'save advances revision');
select private.discard_uninitialized_playground('00000000-0000-4000-8000-000000009801',(select id from project));
select ok(exists(select 1 from private.learn_playgrounds where id=(select id from project)),'cleanup retains an already published project');
create temp table unfinished_project(id uuid);
insert into unfinished_project select private.create_learn_playground('00000000-0000-4000-8000-000000009801','Unfinished','python');
select private.discard_uninitialized_playground('00000000-0000-4000-8000-000000009802',(select id from unfinished_project));
select ok(exists(select 1 from private.learn_playgrounds where id=(select id from unfinished_project)),'cleanup cannot delete another owner project');
select private.discard_uninitialized_playground('00000000-0000-4000-8000-000000009801',(select id from unfinished_project));
select ok(not exists(select 1 from private.learn_playgrounds where id=(select id from unfinished_project)),'failed initial save releases the project quota');
select throws_ok($q$select private.publish_learn_playground('00000000-0000-4000-8000-000000009801',(select id from project),0,'playgrounds/'||(select id from project)||'/'||gen_random_uuid(),'python main.py','[]'::jsonb)$q$,'40001',null,'stale save rejected');
update private.account_benefits set starts_at=now()-interval '1 day',expires_at=now()-interval '1 second' where user_id='00000000-0000-4000-8000-000000009801';
select ok(not private.account_playgrounds_allowed('00000000-0000-4000-8000-000000009801'),'expired benefit denies execution');
-- Only the current confirmed host identity can elevate this exact meeting.
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values('00000000-0000-4000-8000-000000009803','host@tuturuuu.com',now(),'{}');
insert into public.workspace_meetings(id,ws_id,name,creator_id) values('00000000-0000-4000-8000-000000009804',private.account_personal_workspace('00000000-0000-4000-8000-000000009803'),'Disposable coding meeting','00000000-0000-4000-8000-000000009803');
select ok(private.meeting_programming_elevated('00000000-0000-4000-8000-000000009804','00000000-0000-4000-8000-000000009803'),'confirmed exact-domain host elevates the meeting');
select ok(not private.meeting_programming_elevated('00000000-0000-4000-8000-000000009804','00000000-0000-4000-8000-000000009801'),'another actor cannot claim host elevation');
select lives_ok($q$select private.create_learn_playground('00000000-0000-4000-8000-000000009803','Room fixture','python','00000000-0000-4000-8000-000000009804')$q$,'free confirmed host can create a room-scoped playground');
select ok(not private.account_playgrounds_allowed('00000000-0000-4000-8000-000000009803'),'room elevation never creates a permanent account benefit');
update auth.users set email_confirmed_at=null where id='00000000-0000-4000-8000-000000009803';
select ok(not private.meeting_programming_elevated('00000000-0000-4000-8000-000000009804','00000000-0000-4000-8000-000000009803'),'unconfirmed host cannot elevate');
update auth.users set email='host@tuturuuu.com.evil.example',email_confirmed_at=now() where id='00000000-0000-4000-8000-000000009803';
select ok(not private.meeting_programming_elevated('00000000-0000-4000-8000-000000009804','00000000-0000-4000-8000-000000009803'),'lookalike suffix cannot elevate');
-- Credit allocation is exactly once, even when the operator retries a successful request.
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000009802','MEMBER') on conflict(ws_id,user_id) do nothing;
create temp table grant_payload(value jsonb);
insert into grant_payload values(jsonb_build_object('requestId',gen_random_uuid(),'userId','00000000-0000-4000-8000-000000009801','key','ai_credits','amount',123,'reason','Disposable credit fixture'));
select lives_ok($q$select private.grant_account_benefit('00000000-0000-4000-8000-000000009802',(select value from grant_payload))$q$,'credit grant succeeds');
select lives_ok($q$select private.grant_account_benefit('00000000-0000-4000-8000-000000009802',(select value from grant_payload))$q$,'identical grant replay succeeds');
select is((select count(*)::integer from public.ai_credit_transactions where metadata->>'account_benefit_id'=(select value->>'requestId' from grant_payload)),1,'credit replay records exactly one allocation');
select throws_ok($q$select private.grant_account_benefit('00000000-0000-4000-8000-000000009802',(select value||'{"amount":124}'::jsonb from grant_payload))$q$,'40001',null,'conflicting credit replay rejected');
select throws_ok($q$select private.revoke_account_benefit('00000000-0000-4000-8000-000000009802',(select (value->>'requestId')::uuid from grant_payload))$q$,'P0002',null,'delivered AI credits cannot be revoked as a feature flag');
-- Cloudflare tickets preserve account and workspace isolation.
select ok(not has_function_privilege('authenticated','private.cloudflare_channel_role(uuid,text)','EXECUTE'),'browser cannot mint tickets through the service authorization RPC');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','task-user-realtime-00000000-0000-4000-8000-000000009801'),'editor','actor can join their personal task fanout');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009802','task-user-realtime-00000000-0000-4000-8000-000000009801'),null,'actor cannot join another personal task fanout');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-not-a-uuid'),null,'malformed topics deny without exceptions');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','meeting-document-00000000-0000-4000-8000-000000009804'),null,'meeting admission cannot be bypassed through workspace ticket authorization');
insert into public.workspaces(id,name,creator_id,personal) values('00000000-0000-4000-8000-000000009806','Channel fixture workspace','00000000-0000-4000-8000-000000009803',false);
insert into public.workspace_boards(id,ws_id,name,creator_id) values('00000000-0000-4000-8000-000000009805','00000000-0000-4000-8000-000000009806','Channel fixture','00000000-0000-4000-8000-000000009803');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-00000000-0000-4000-8000-000000009805'),null,'foreign board ticket denied');
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-4000-8000-000000009806','00000000-0000-4000-8000-000000009801','GUEST');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-00000000-0000-4000-8000-000000009805'),null,'guest workspace membership does not authorize a board without a share');
insert into public.task_board_shares(board_id,shared_with_user_id,shared_by_user_id,permission) values('00000000-0000-4000-8000-000000009805','00000000-0000-4000-8000-000000009801','00000000-0000-4000-8000-000000009803','view');
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-00000000-0000-4000-8000-000000009805'),'viewer','guest view share issues read-only ticket');
update public.task_board_shares set permission='edit' where board_id='00000000-0000-4000-8000-000000009805';
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-00000000-0000-4000-8000-000000009805'),'editor','guest edit share issues editor ticket');
update public.workspace_boards set deleted_at=now() where id='00000000-0000-4000-8000-000000009805';
select is(private.cloudflare_channel_role('00000000-0000-4000-8000-000000009801','board-realtime-00000000-0000-4000-8000-000000009805'),null,'deleted board loses ticket access');
-- Meeting documents are private, stable across joins, and checkpoint order is monotonic.
select ok(not has_function_privilege('authenticated','private.read_meeting_document(uuid)','EXECUTE'),'browser cannot manufacture document membership');
create temp table meeting_document(value jsonb);
insert into meeting_document select private.read_meeting_document('00000000-0000-4000-8000-000000009804');
select is(private.read_meeting_document('00000000-0000-4000-8000-000000009804')->>'documentId',(select value->>'documentId' from meeting_document),'repeated join uses the same document');
select ok(not (select is_public from public.workspace_documents where id=(select (value->>'documentId')::uuid from meeting_document)),'meeting document is private by default');
select is(private.checkpoint_meeting_document('00000000-0000-4000-8000-000000009804',(select (value->>'documentId')::uuid from meeting_document),'00000000-0000-4000-8000-000000009803','[1,2]','{"type":"doc","content":[]}',repeat('a',64),2),2,'checkpoint exports document at signed version');
select is(private.checkpoint_meeting_document('00000000-0000-4000-8000-000000009804',(select (value->>'documentId')::uuid from meeting_document),'00000000-0000-4000-8000-000000009803','[3]','{"type":"doc","content":[]}',repeat('b',64),1),2,'late older checkpoint never rewinds the document');
select is(private.read_meeting_document('00000000-0000-4000-8000-000000009804')->'state','[1,2]'::jsonb,'late callback retains the newest state');
select throws_ok($q$select private.checkpoint_meeting_document('00000000-0000-4000-8000-000000009804',(select (value->>'documentId')::uuid from meeting_document),'00000000-0000-4000-8000-000000009801','[]','{"type":"doc"}',repeat('a',64),3)$q$,'42501',null,'foreign owner cannot checkpoint meeting document');
update public.workspace_documents set content='{"type":"doc","content":[{"type":"paragraph"}]}' where id=(select (value->>'documentId')::uuid from meeting_document);
select throws_ok($q$select private.checkpoint_meeting_document('00000000-0000-4000-8000-000000009804',(select (value->>'documentId')::uuid from meeting_document),'00000000-0000-4000-8000-000000009803','[4]','{"type":"doc","content":[]}',repeat('c',64),4)$q$,'40001',null,'room checkpoint cannot overwrite an external document edit');
select is((select content from public.workspace_documents where id=(select (value->>'documentId')::uuid from meeting_document)),'{"type":"doc","content":[{"type":"paragraph"}]}'::jsonb,'external document edit survives stale room callback');
select * from finish();
rollback;
